package com.companybrain.dto;

import java.util.List;

/**
 * Result DTO representing an evidence-grounded answer generated by the local LLM or deterministic fallback.
 *
 * @param question        original user query
 * @param answerText      generated natural-language answer text
 * @param answerType      "LLM_GROUNDED", "DETERMINISTIC_FALLBACK", or "INSUFFICIENT_EVIDENCE"
 * @param graphFacts      verified structural facts from the company graph
 * @param citedPassages   verified document passages cited by the model
 * @param distinctSources verified distinct document sources
 * @param evidenceStatus  availability of underlying evidence
 * @param limitations     factual notes on boundaries and missing information
 * @param fallbackUsed    true if deterministic fallback was triggered
 * @param fallbackReason  reason why fallback was used (null if LLM succeeded)
 */
public record GeneratedAnswer(
        String question,
        String answerText,
        String answerType,
        List<String> graphFacts,
        List<RetrievedPassage> citedPassages,
        List<Evidence> distinctSources,
        EvidenceStatus evidenceStatus,
        List<String> limitations,
        boolean fallbackUsed,
        String fallbackReason
) {
    public GeneratedAnswer {
        if (graphFacts == null) graphFacts = List.of();
        if (citedPassages == null) citedPassages = List.of();
        if (distinctSources == null) distinctSources = List.of();
        if (limitations == null) limitations = List.of();
    }
}
